-- Theme scripts select a border style through a plain-text setting, not a Lua
-- module. The default retains HyprMod's configured styling.
local window_style = "hyprmod"
local style_file = io.open(os.getenv("HOME") .. "/.config/1f2l/hypr-window-style", "r")
if style_file then
    local configured_style = style_file:read("*l")
    style_file:close()
    if configured_style and configured_style ~= "" then
        window_style = configured_style
    end
end

local window_styles = {
    default = {
        gaps_in = 10,
        gaps_out = 20,
        border_size = 2,
        col = {
            active_border = { colors = {colors.primary, colors.on_primary}, angle = 90 },
            inactive_border = colors.on_primary,
        },
    },
    ["border-2"] = {
        gaps_in = 10,
        gaps_out = 20,
        border_size = 2,
        col = {
            active_border = colors.primary,
            inactive_border = colors.primary,
        },
    },
    transparent = {
        gaps_in = 10,
        gaps_out = 20,
        border_size = 1,
        col = {
            active_border = { colors = {"rgb(ffffff)", colors.on_primary}, angle = 90 },
            inactive_border = colors.on_primary,
        },
    },
}

if window_styles[window_style] then
    hl.config({general = window_styles[window_style]})
elseif window_style ~= "hyprmod" then
    io.stderr:write("Unknown Hyprland window style: " .. window_style .. "\n")
end
